#include <format>
#include <string>

std::string price(double amount)
{
    return std::format("${:.2f}", amount);
}

std::string padded(int number)
{
    return std::format("{:05}", number);
}

std::string hexByte(int value)
{
    return std::format("0x{:02X}", value);
}

unitTests:
TEST("price") { CHECK_EQ(price(3.5), "$3.50"); CHECK_EQ(price(1234.567), "$1234.57"); CHECK_EQ(price(0), "$0.00"); }
TEST("padded") { CHECK_EQ(padded(42), "00042"); CHECK_EQ(padded(7), "00007"); CHECK_EQ(padded(123456), "123456"); }
TEST("hexByte") { CHECK_EQ(hexByte(255), "0xFF"); CHECK_EQ(hexByte(10), "0x0A"); CHECK_EQ(hexByte(0), "0x00"); }

